// FUNCTION: BFME2 0x0048B7FD size=315 name=?update@FireSpreadUpdate@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger tier=B hypothesis:Z
UpdateSleepTime FireSpreadUpdate::update()
{
	const FireSpreadUpdateModuleData *md = static_cast<const FireSpreadUpdateModuleData *>(getModuleData());
	Object *me = getObject();

	if (!me->testStatus((ObjectStatusTypes)10))
		return UPDATE_SLEEP_FOREVER;

	{
		if (md->m_oclEmbers)
			const_cast<ObjectCreationList *>(md->m_oclEmbers)->create(me, NULL, NULL);

		if (md->m_spreadTryRange != 0)
		{
			// This will spread fire explicitly
			Object *objectToLight;
			{
				PartitionFilterFlammable fFilter;
				objectToLight = ThePartitionManager->getClosestObject(getObject()->getPosition(), md->m_spreadTryRange, 2, &fFilter);
			}
			if (objectToLight == NULL && TheAI->getAiData()->m_allowForestFires)
			{
				void *found = (void *)TheTerrainLogic->rva0027F108((void *)me->getPosition(), md->m_spreadTryRange, 1, 0);
				if (found)
					objectToLight = TheTerrainLogic->rva00283D70((const Coord3D *)found);
			}
			if (objectToLight)
			{
				static NameKeyType key_FlammableUpdate = TheNameKeyGenerator->nameToKey("FlammableUpdate");
				FlammableUpdate *fu = (FlammableUpdate *)objectToLight->findUpdateModule(key_FlammableUpdate);
				if (fu)
					fu->tryToIgnite();
			}
		}

		return UPDATE_SLEEP(calcNextSpreadDelay());
	}
}

// FUNCTION: BFME2 0x0048B938 size=39 name=?startFireSpreading@FireSpreadUpdate@@QAEXXZ evidence=N:ledger tier=B hypothesis:Z
void FireSpreadUpdate::startFireSpreading()
{
	Object *object = m_object;
	if (object->testStatus((ObjectStatusTypes)10))
		setWakeFrame(object, (UpdateSleepTime)calcNextSpreadDelay());
}


